// The Hop mark as a live connection indicator.
// Generated by design/scripts/generate.py; edit there.
package dot.vpn.payam.ui

import android.provider.Settings
import androidx.compose.animation.animateColorAsState
import androidx.compose.animation.core.Animatable
import androidx.compose.animation.core.CubicBezierEasing
import androidx.compose.animation.core.LinearEasing
import androidx.compose.animation.core.RepeatMode
import androidx.compose.animation.core.animateFloat
import androidx.compose.animation.core.infiniteRepeatable
import androidx.compose.animation.core.rememberInfiniteTransition
import androidx.compose.animation.core.tween
import androidx.compose.foundation.Canvas
import androidx.compose.foundation.layout.size
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.drawscope.scale
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.semantics.contentDescription
import androidx.compose.ui.semantics.semantics
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import dot.vpn.payam.ui.theme.DotTheme

enum class HopState { Off, Connecting, Connected, Failed }

private val DotEase = CubicBezierEasing(0.4f, 0f, 0.2f, 1f)
private val PathDots = listOf(
    Offset(15.019f, 45.512f),
    Offset(16.099f, 36.587f),
    Offset(19.202f, 28.166f),
    Offset(25.356f, 21.739f),
    Offset(33.880f, 19.083f),
)
private val P0 = Offset(15f, 46f)
private val P1 = Offset(16f, 18f)
private val P2 = Offset(38f, 19f)

private fun along(t: Float): Offset {
    val u = 1f - t
    return P0 * (u * u) + P1 * (2f * u * t) + P2 * (t * t)
}

/**
 * Off: grey path and dot. Connecting: a lime traveller hops along the path
 * every 700ms. Connected: the big dot fills lime (200ms, scale 0.9 to 1).
 * Failed: the big dot turns danger. Respects "Remove animations".
 */
@Composable
fun HopMark(
    state: HopState,
    label: String,
    modifier: Modifier = Modifier,
    size: Dp = 40.dp,
) {
    val c = DotTheme.colors
    val context = LocalContext.current
    val reduceMotion = remember {
        Settings.Global.getFloat(context.contentResolver, Settings.Global.ANIMATOR_DURATION_SCALE, 1f) == 0f
    }
    val big by animateColorAsState(
        when (state) {
            HopState.Connected -> c.signal
            HopState.Failed -> c.danger
            else -> c.off
        },
        tween(if (state == HopState.Connected) 200 else 150), label = "hop-dot",
    )
    val path by animateColorAsState(if (state == HopState.Connected) c.fg else c.off, tween(200), label = "hop-path")
    val pop = remember { Animatable(1f) }
    LaunchedEffect(state) {
        if (state == HopState.Connected && !reduceMotion) {
            pop.snapTo(0.9f); pop.animateTo(1f, tween(200, easing = DotEase))
        }
    }
    val travel = rememberInfiniteTransition(label = "hop")
    val t by travel.animateFloat(0f, 1f, infiniteRepeatable(tween(700, easing = DotEase), RepeatMode.Restart), label = "hop-t")

    Canvas(modifier.size(size).semantics { contentDescription = label }) {
        val k = this.size.minDimension / 64f
        scale(k, pivot = Offset.Zero) {
            PathDots.forEach { drawCircle(path, 2.6f, it) }
            drawCircle(c.fg, 6f, Offset(14f, 48f))
            val centre = Offset(46f, 20f)
            if (c.isLight) {
                drawCircle(c.fg, 10.5f * pop.value, centre)
                drawCircle(big, 6.5f * pop.value, centre)
            } else {
                drawCircle(big, 9.5f * pop.value, centre)
            }
            if (state == HopState.Connecting && !reduceMotion) {
                drawCircle(c.signal, 3.5f, along(t))
            }
        }
    }
}
